"use client";

import * as React from "react";
import styles from "../styles/horizontal-scroll.module.css";

interface SmoothScrollState {
  /** Current scrollTop of the viewport in px */
  scroll: number;
  /** Maximum scrollTop in px */
  limit: number;
  /** scroll / limit, 0..1 */
  progress: number;
  /** Signed scroll velocity in px per 60fps frame */
  velocity: number;
}

interface SmoothScrollOptions {
  lerp: number;
  wheelMultiplier: number;
  smooth: boolean;
  onScroll?: (state: SmoothScrollState) => void;
}

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** True when a nested scrollable element under the pointer can still scroll in the wheel direction. */
function nestedCanScroll(node: EventTarget | null, root: HTMLElement, dy: number): boolean {
  let el: Element | null = node instanceof Element ? node : null;
  while (el && el !== root) {
    if (el instanceof HTMLElement) {
      if (el.dataset.mfScrollPrevent !== undefined) return true;
      const overflowY = window.getComputedStyle(el).overflowY;
      if ((overflowY === "auto" || overflowY === "scroll") && el.scrollHeight > el.clientHeight + 1) {
        const canMove = dy < 0 ? el.scrollTop > 0 : el.scrollTop + el.clientHeight < el.scrollHeight - 1;
        if (canMove) return true;
      }
    }
    el = el.parentElement;
  }
  return false;
}

/**
 * Self-contained smooth scroller for an overflow container. Wheel input updates a target
 * position; a rAF loop eases the real scrollTop toward it (frame-rate independent lerp) and
 * stops once settled. Touch, keyboard and scrollbar drags stay native. At the top/bottom edge
 * wheel events are released so the page keeps scrolling.
 */
function useSmoothScroll(
  containerRef: React.RefObject<HTMLElement | null>,
  { lerp, wheelMultiplier, smooth, onScroll }: SmoothScrollOptions,
): React.RefObject<SmoothScrollState> {
  const stateRef = React.useRef<SmoothScrollState>({ scroll: 0, limit: 0, progress: 0, velocity: 0 });
  const callbackRef = React.useRef(onScroll);
  React.useEffect(() => {
    callbackRef.current = onScroll;
  }, [onScroll]);

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ease = clamp(Number.isFinite(lerp) ? lerp : 0.1, 0.01, 1);
    const multiplier = Number.isFinite(wheelMultiplier) ? wheelMultiplier : 1;
    let target = el.scrollTop;
    let current = target;
    let raf = 0;
    let lastTime = 0;
    let lastNative = el.scrollTop;
    let lastNativeTime = 0;
    let settleTimer: ReturnType<typeof setTimeout> | undefined;

    const getLimit = () => Math.max(0, el.scrollHeight - el.clientHeight);

    const emit = (velocity: number) => {
      const limit = getLimit();
      const scroll = clamp(el.scrollTop, 0, limit);
      lastNative = el.scrollTop;
      const s = stateRef.current;
      s.scroll = scroll;
      s.limit = limit;
      s.progress = limit > 0 ? scroll / limit : 0;
      s.velocity = velocity;
      callbackRef.current?.(s);
    };

    const tick = (time: number) => {
      const dt = lastTime ? Math.min(64, Math.max(1, time - lastTime)) : 16.667;
      lastTime = time;
      const limit = getLimit();
      target = clamp(target, 0, limit);
      if (Math.abs(el.scrollTop - current) > 2) {
        // Something else moved the viewport (scrollbar drag, keyboard, touch): hand control back.
        current = target = el.scrollTop;
        raf = 0;
        lastTime = 0;
        emit(0);
        return;
      }
      const prev = current;
      const frames = dt / 16.667;
      current += (target - current) * (1 - Math.pow(1 - ease, frames));
      if (Math.abs(target - current) < 0.35) current = target;
      el.scrollTop = current;
      emit((current - prev) / frames);
      if (current === target) {
        raf = 0;
        lastTime = 0;
        emit(0);
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const onWheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.defaultPrevented) return;
      if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return;
      let dy = event.deltaY;
      if (event.deltaMode === 1) dy *= 16;
      else if (event.deltaMode === 2) dy *= el.clientHeight;
      dy *= multiplier;
      if (dy === 0 || nestedCanScroll(event.target, el, dy)) return;
      const limit = getLimit();
      if (!raf) current = target = el.scrollTop;
      // Release to native scrolling at the edges so the page is never trapped.
      if ((dy < 0 && target <= 0) || (dy > 0 && target >= limit - 0.5)) return;
      event.preventDefault();
      target = clamp(target + dy, 0, limit);
      if (!raf) {
        lastTime = 0;
        raf = requestAnimationFrame(tick);
      }
    };

    const onNativeScroll = () => {
      if (raf) return;
      const top = el.scrollTop;
      const delta = top - lastNative;
      if (delta === 0) return;
      const now = performance.now();
      const dt = lastNativeTime ? clamp(now - lastNativeTime, 8, 100) : 16.667;
      lastNativeTime = now;
      current = target = top;
      emit(delta / (dt / 16.667));
      if (settleTimer) clearTimeout(settleTimer);
      settleTimer = setTimeout(() => {
        lastNativeTime = 0;
        emit(0);
      }, 90);
    };

    if (smooth) el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", onNativeScroll, { passive: true });
    const ro = new ResizeObserver(() => emit(stateRef.current.velocity));
    ro.observe(el);
    if (el.firstElementChild) ro.observe(el.firstElementChild);
    emit(0);

    return () => {
      if (smooth) el.removeEventListener("wheel", onWheel);
      el.removeEventListener("scroll", onNativeScroll);
      ro.disconnect();
      if (raf) cancelAnimationFrame(raf);
      if (settleTimer) clearTimeout(settleTimer);
    };
  }, [containerRef, lerp, wheelMultiplier, smooth]);

  return stateRef;
}

export interface HorizontalScrollProps {
  /** Card titles, one card per item */
  items?: string[];
  /** Heading shown above the track */
  title?: string;
  /** Card width in px */
  cardWidth?: number;
  /** Gap between cards in px */
  gap?: number;
  /** Accent color for card art, counter and progress */
  accentColor?: string;
  /** Viewport height in px */
  height?: number;
  /** Viewport corner radius in px */
  borderRadius?: number;
  /** Interpolation factor per 60fps frame (0.05 = floaty, 0.3 = snappy) */
  lerp?: number;
  /** Multiplier applied to wheel / trackpad deltas */
  wheelMultiplier?: number;
  /** Enable smooth wheel scrolling (native scrolling when false or under reduced motion) */
  smooth?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_ITEMS = ["Discover", "Sketch", "Prototype", "Refine", "Animate", "Ship"];

export function HorizontalScroll({
  items = DEFAULT_ITEMS,
  title = "Scroll down, travel sideways",
  cardWidth = 260,
  gap = 20,
  accentColor = "#38bdf8",
  height = 380,
  borderRadius = 20,
  lerp = 0.1,
  wheelMultiplier = 1,
  smooth = true,
  className = "",
  style,
}: HorizontalScrollProps) {
  const reduced = usePrefersReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const viewportRef = React.useRef<HTMLDivElement>(null);
  const spacerRef = React.useRef<HTMLDivElement>(null);
  const stageRef = React.useRef<HTMLDivElement>(null);
  const trackRef = React.useRef<HTMLUListElement>(null);
  const counterRef = React.useRef<HTMLSpanElement>(null);
  const travelRef = React.useRef(0);
  const progressRef = React.useRef(0);
  const total = items.length;

  const apply = React.useCallback(() => {
    const root = rootRef.current;
    if (!root) return;
    const p = progressRef.current;
    root.style.setProperty("--mf-hs-x", `${(-p * travelRef.current).toFixed(2)}px`);
    root.style.setProperty("--mf-hs-p", p.toFixed(4));
    const counter = counterRef.current;
    if (counter && total > 0) {
      const index = Math.min(total, Math.floor(p * total) + 1);
      counter.textContent = `${String(index).padStart(2, "0")} / ${String(total).padStart(2, "0")}`;
    }
  }, [total]);

  const handleScroll = React.useCallback(
    (state: SmoothScrollState) => {
      progressRef.current = state.progress;
      apply();
    },
    [apply],
  );

  useSmoothScroll(viewportRef, { lerp, wheelMultiplier, smooth: smooth && !reduced, onScroll: handleScroll });

  React.useEffect(() => {
    const stage = stageRef.current;
    const track = trackRef.current;
    const spacer = spacerRef.current;
    if (!stage || !track || !spacer) return;
    const measure = () => {
      const travel = Math.max(0, track.scrollWidth - stage.clientWidth);
      travelRef.current = travel;
      spacer.style.height = `${Math.round(height + travel)}px`;
      apply();
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(stage);
    ro.observe(track);
    return () => ro.disconnect();
  }, [height, cardWidth, gap, total, apply]);

  const vars = {
    "--mf-hs-h": `${height}px`,
    "--mf-hs-r": `${borderRadius}px`,
    "--mf-hs-accent": accentColor,
    "--mf-hs-card": `${cardWidth}px`,
    "--mf-hs-gap": `${gap}px`,
    ...style,
  } as React.CSSProperties;

  return (
    <div ref={rootRef} style={vars} className={`${styles.root} ${className}`.trim()}>
      <div ref={viewportRef} className={styles.viewport} tabIndex={0} role="region" aria-label={title}>
        <div ref={spacerRef} className={styles.spacer} style={{ height: `${Math.round(height * 2.6)}px` }}>
          <div ref={stageRef} className={styles.stage}>
            <div className={styles.header}>
              <h3 className={styles.title}>{title}</h3>
              <span ref={counterRef} aria-hidden="true" className={styles.counter}>
                {`01 / ${String(total).padStart(2, "0")}`}
              </span>
            </div>
            <ul ref={trackRef} className={styles.track}>
              {items.map((item, i) => (
                <li key={`${item}-${i}`} className={styles.card} style={{ "--mf-hs-i": i } as React.CSSProperties}>
                  <span aria-hidden="true" className={styles.art} />
                  <span className={styles.index}>{String(i + 1).padStart(2, "0")}</span>
                  <span className={styles.cardTitle}>{item}</span>
                </li>
              ))}
            </ul>
            <div aria-hidden="true" className={styles.progress}>
              <span className={styles.progressFill} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

.root {
  --mf-hs-x: 0px;
  --mf-hs-p: 0;
  position: relative;
  width: 100%;
  height: var(--mf-hs-h, 380px);
  border-radius: var(--mf-hs-r, 20px);
  overflow: hidden;
  border: 1px solid var(--mf-border, #2e2e38);
  background: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  container-type: inline-size;
  isolation: isolate;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.viewport {
  position: relative;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: auto;
  scroll-behavior: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--mf-border, #2e2e38) transparent;
}

.viewport:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: -2px;
}

.spacer {
  position: relative;
}

.stage {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1.1rem;
  height: var(--mf-hs-h, 380px);
  overflow: hidden;
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding: 0 clamp(1.25rem, 5cqi, 2.5rem);
}

.title {
  margin: 0;
  font-size: clamp(1.15rem, 3.4cqi, 1.6rem);
  font-weight: 600;
  letter-spacing: -0.025em;
}

.counter {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.8rem;
  font-variant-numeric: tabular-nums;
  color: var(--mf-hs-accent, #38bdf8);
}

.track {
  display: flex;
  gap: var(--mf-hs-gap, 20px);
  width: max-content;
  margin: 0;
  padding: 0 clamp(1.25rem, 5cqi, 2.5rem);
  list-style: none;
  transform: translate3d(var(--mf-hs-x, 0px), 0, 0);
  will-change: transform;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 0.3rem;
  flex: 0 0 var(--mf-hs-card, 260px);
  height: calc(var(--mf-hs-h, 380px) * 0.58);
  padding: 1.1rem 1.2rem;
  border: 1px solid var(--mf-border, #2e2e38);
  border-radius: 18px;
  background: var(--mf-surface-raised, #1b1b22);
  overflow: hidden;
}

.art {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 75% 20%, color-mix(in srgb, var(--mf-hs-accent, #38bdf8) 65%, transparent), transparent 55%),
    radial-gradient(circle at 15% 90%, color-mix(in srgb, var(--mf-hs-accent, #38bdf8) 25%, #a78bfa), transparent 50%),
    linear-gradient(180deg, transparent 40%, color-mix(in srgb, var(--mf-bg, #09090b) 85%, transparent));
  filter: hue-rotate(calc(var(--mf-hs-i, 0) * 32deg));
  opacity: 0.85;
}

.art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.05) 0 1px, transparent 1px 22px);
}

.index {
  position: relative;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.75rem;
  color: var(--mf-muted, #a1a1aa);
}

.cardTitle {
  position: relative;
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.progress {
  margin: 0 clamp(1.25rem, 5cqi, 2.5rem);
  height: 2px;
  border-radius: 2px;
  background: var(--mf-border, #2e2e38);
  overflow: hidden;
}

.progressFill {
  display: block;
  height: 100%;
  background: var(--mf-hs-accent, #38bdf8);
  transform: scaleX(var(--mf-hs-p, 0));
  transform-origin: left center;
}

@media (prefers-reduced-motion: reduce) {
  .track {
    will-change: auto;
  }
}

